"""Configuration source loader with precedence layers."""

from typing import Any, Dict
from defaults import DEFAULT_CONFIG


def deep_clone(d: Dict[str, Any]) -> Dict[str, Any]:
    res = {}
    for k, v in d.items():
        res[k] = deep_clone(v) if isinstance(v, dict) else v
    return res


class ConfigLoader:
    """Loads configuration by applying layers in order: Defaults -> File -> Env -> Cli."""

    def __init__(self):
        self.layers: list[Dict[str, Any]] = []

    def add_layer(self, layer_dict: Dict[str, Any]) -> None:
        if layer_dict:
            self.layers.append(deep_clone(layer_dict))

    def build_effective_config(self) -> Dict[str, Any]:
        result = deep_clone(DEFAULT_CONFIG)
        # BUG: Layer merging is shallow and overwrites entire sub-dictionaries
        # instead of performing recursive deep property updates.
        for layer in self.layers:
            for section, values in layer.items():
                if section in result and isinstance(values, dict):
                    result[section] = values  # Replaces entire section, losing unmentioned defaults!
                else:
                    result[section] = values
        return result

repo_files.config.py:
"""Application configuration accessor and validation."""

from typing import Any, Dict, Optional
from loader import ConfigLoader


class AppConfig:
    def __init__(self, loader: ConfigLoader):
        self.loader = loader
        self._data: Optional[Dict[str, Any]] = None

    def reload(self) -> None:
        self._data = self.loader.build_effective_config()

    def get(self, path: str, default: Any = None) -> Any:
        if self._data is None:
            self.reload()
        assert self._data is not None
        keys = path.split(".")
        curr: Any = self._data
        for k in keys:
            if not isinstance(curr, dict) or k not in curr:
                return default
            curr = curr[k]
        # BUG: If the value in config is explicitly None, returns default instead of None
        return default if curr is None else curr

